SELECT timeSeriesStoreTags(id, tags, '__name__', metric_name) FROM default.`.inner_id.tags.a95d167f-9ea5-48c0-bd90-d75fef42985c` ANY LEFT JOIN (SELECT id, 1 AS matched FROM default.`.inner_id.timeranges.a95d167f-9ea5-48c0-bd90-d75fef42985c` WHERE and(greaterOrEquals(max_time, toDateTime64(toDecimal128('1794609600.001', 3), 3)), lessOrEquals(min_time, toDateTime64(toDecimal128('1794620700', 3), 3)))) AS time_ranges_subquery USING (id) WHERE and(and(match(metric_name, '^metric_.*$'), equals(arrayElement(tags, 'namespace'), 'ns3')), equals(time_ranges_subquery.matched, 1))
